def fill_dynamic(segments, H=16,W=16):
    # segments tuple d,rstart,rend; activate each diagonal over continuous u projection
    us=range(0,H+W-1)
    active_by_u={}
    for u in us:
        ds=[]
        for d,a,b in segments:
            if 2*a+d<=u<=2*b+d:
                ds.append(d)
        active_by_u[u]=sorted(set(ds))
    cells=set()
    for r in range(H):
      for c in range(W):
        d=c-r;u=c+r
        act=active_by_u[u]
        if any(dl<d<dr for dl,dr in zip(act,act[1:])):
          cells.add((r,c))
